        /// <summary>
        /// For an inline array struct, warn about custom members (indexers, 'Slice' methods, and
        /// conversion operators to spans) that will not be used because the language provides
        /// built-in mechanisms for element access and span conversions.
        /// </summary>
        private void CheckForInlineArrayBypassedMembers(BindingDiagnosticBag diagnostics)
        {
            var compilation = DeclaringCompilation;
            var indexType = compilation.GetWellKnownType(WellKnownType.System_Index);
            var rangeType = compilation.GetWellKnownType(WellKnownType.System_Range);
            TypeSymbol? elementType = TryGetInlineArrayElementField()?.Type;

            foreach (var member in GetMembers())
            {
                switch (member)
                {
                    case PropertySymbol { IsIndexer: true, IsExplicitInterfaceImplementation: false } indexer
                        when !IsRefLikeType:
                        {
                            if (indexer.Parameters is [{ Type: var parameterType }] &&
                                (parameterType.SpecialType == SpecialType.System_Int32 ||
                                 TypeSymbol.Equals(parameterType, indexType, TypeCompareKind.ConsiderEverything) ||
                                 TypeSymbol.Equals(parameterType, rangeType, TypeCompareKind.ConsiderEverything)))
                            {
                                diagnostics.Add(ErrorCode.WRN_InlineArrayIndexerNotUsed, indexer.GetFirstLocation());
                            }
                        }
                        break;

                    case MethodSymbol { MethodKind: MethodKind.Ordinary, Name: "Slice", IsExplicitInterfaceImplementation: false } sliceMethod:
                        {
                            if (!sliceMethod.ReturnsVoid &&
                                sliceMethod.Parameters is [{ Type.SpecialType: SpecialType.System_Int32 }, { Type.SpecialType: SpecialType.System_Int32 }])
                            {
                                diagnostics.Add(ErrorCode.WRN_InlineArraySliceNotUsed, sliceMethod.GetFirstLocation());
                            }
                        }
                        break;

                    case MethodSymbol { MethodKind: MethodKind.Conversion } conversion:
                        {
                            if (elementType is not null &&
                                conversion.Parameters is [{ Type: var sourceType }] &&
                                sourceType.Equals(this, TypeCompareKind.ConsiderEverything) &&
                                isSpanOrReadOnlySpanOfElementType(conversion.ReturnType, elementType))
                            {
                                diagnostics.Add(ErrorCode.WRN_InlineArrayConversionOperatorNotUsed, conversion.GetFirstLocation());
                            }
                        }
                        break;
                }
            }

            bool isSpanOrReadOnlySpanOfElementType(TypeSymbol type, TypeSymbol elementType)
            {
                return type is NamedTypeSymbol
                {
                    ContainingNamespace: { Name: "System", ContainingNamespace: { IsGlobalNamespace: true } },
                    MetadataName: "Span`1" or "ReadOnlySpan`1",
                    TypeArgumentsWithAnnotationsNoUseSiteDiagnostics: [var argument],
                }
                && argument.Type.Equals(elementType, TypeCompareKind.ConsiderEverything);
            }
        }
    }
